import * as React from "react";
import { cx } from "./cx";

export interface ItemProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  title: React.ReactNode;
  description?: React.ReactNode;
  meta?: React.ReactNode;
}

/** A flush row. Title occupies the cell; meta trails. */
export function Item({ title, description, meta, className, ...props }: ItemProps) {
  return (
    <div className={cx("rs-item", className)} {...props}>
      <div>
        <p className="rs-item-title">{title}</p>
        {description != null && <p className="rs-item-desc">{description}</p>}
      </div>
      {meta != null && <span className="rs-item-meta">{meta}</span>}
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Item: a flush row. Title, note, trailing meta ── */
.rs-item{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:48px;padding:10px 0;border-bottom:1px solid var(--divider);border-radius:0}
.rs-item:last-child{border-bottom:none}
.rs-item-title{margin:0;font-size:14px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-item-desc{margin:2px 0 0;font-size:12.5px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary)}
.rs-item-meta{font-size:12px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary);flex-shrink:0}
